import json
from cpmpy import Model, intvar

# Decision variables: 18 holes, each length in {3,4,5}
holes = intvar(3, 5, shape=18, name="holes")

# Model: total length must be 72
model = Model(sum(holes) == 72)

if model.solve():
    solution = {'holes': [int(h.value()) for h in holes]}
    print(json.dumps(solution))
else:
    print("No solution found.")
